  const pedidos = await Promise.all(
    (data ?? []).map(async (o: any) => {
      const { data: itensRaw } = await this.supabase.client
        .from('order_items')
        .select('id, quantity, unit_price, product_id')
        .eq('order_id', o.id);

      let itens: any[] = itensRaw ?? [];
      if (itens.length > 0) {
        const prodIds = itens.map((i) => i.product_id);
        const { data: prods } = await this.supabase.client
          .from('products').select('id, name').in('id', prodIds);
        const prodMap = Object.fromEntries((prods ?? []).map((p: any) => [p.id, p.name]));
        itens = itens.map((i) => ({ ...i, product_name: prodMap[i.product_id] ?? `Produto #${i.product_id}` }));
      }
      return { ...o, itens };
    }),
  );
  return { pedidos };
}

// KDS por setor (módulo Salão): tela genérica reaproveitável por impressora/setor
// (cozinha, bar, salgados...) — lista PLANA de itens (não agrupa por mesa/comanda,
// cada item tem sua própria ação de preparo/impressão), ordenada por chegada.
async getKdsSetor(restaurantId: number, impressoraId: number) {
  // Itens "pronto" de hoje inteiro também entram — sem isso, um clique errado em
  // "Entregue"/"Pronto" faz o item sumir da tela sem chance de desfazer. A tela
  // (Cozinha/Produção) que decide mostrar só os últimos N com opção de expandir.
  const inicioDoDia = new Date();
  inicioDoDia.setHours(0, 0, 0, 0);
  const limiteProntos = inicioDoDia.toISOString();
  const { data: itens, error } = await this.supabase.client
    .from('order_items')
    .select('id, quantity, unit_price, observacao, product_id, status, enviado_em, preparando_em, pronto_em, entregue_garcom, garcom_nao_entregou, garcom_indo_buscar, ordem_fila, order_id, products(name), orders(id, restaurant_id, mesa_id, cliente_mesa_nome, garcom_id, customer_id, status, numero_comanda, is_venda_balcao, aberto_por_nome, motoboy_lat, motoboy_lng, delivery_occurrence, total, payment_method, created_at, mesas(numero, nome), garcons(nome))')
    .eq('impressora_id', impressoraId)
    .or(`status.in.(enviado,preparando),and(status.eq.pronto,pronto_em.gte.${limiteProntos})`)
    .order('ordem_fila', { ascending: true, nullsFirst: false })
    .order('enviado_em', { ascending: true });
  if (error) throw error;

  const itensValidos = (itens as any[]).filter((i) => i.orders?.restaurant_id === restaurantId);

  // Um item roteado pra uma impressora/setor pode vir tanto de comanda do salão
  // (mesa_id/garcom_id preenchidos) quanto de pedido de delivery (produto com a
  // mesma impressora configurada) — resolve nome do cliente de delivery à parte
  // pra tela poder filtrar e exibir por canal.
  const customerIds = [...new Set(itensValidos.map((i) => i.orders?.customer_id).filter(Boolean))];
  const { data: customers } = customerIds.length
    ? await this.supabase.client.from('customers').select('id, name').in('id', customerIds)
    : { data: [] as any[] };
  const customerMap = Object.fromEntries((customers ?? []).map((c: any) => [c.id, c.name]));

  return {
    itens: itensValidos.map((i) => {
      const ehSalao = !!(i.orders?.mesa_id || i.orders?.garcom_id || i.orders?.cliente_mesa_nome);
      const ehAutoAtendimento = i.orders?.aberto_por_nome === 'Auto Atendimento';
      return {
        id: i.id,
        order_id: i.order_id,
        product_name: i.products?.name,
        quantity: i.quantity,
        observacao: i.observacao,
        status: i.status,
        enviado_em: i.enviado_em,
        preparando_em: i.preparando_em,
        pronto_em: i.pronto_em,
        entregue_garcom: i.entregue_garcom ?? false,
        garcom_nao_entregou: i.garcom_nao_entregou ?? false,
        garcom_indo_buscar: i.garcom_indo_buscar ?? false,
        tipo: ehSalao ? 'salao' : 'delivery',
        is_auto_atendimento: ehAutoAtendimento,
        mesa: i.orders?.mesas ? `Mesa ${i.orders.mesas.numero}${i.orders.mesas.nome ? ' - ' + i.orders.mesas.nome : ''}` : null,
        mesa_numero: i.orders?.mesas?.numero ?? null,
        numero_comanda: i.orders?.numero_comanda ?? null,
        cliente: i.orders?.cliente_mesa_nome ?? (i.orders?.customer_id ? customerMap[i.orders.customer_id] ?? null : null),
        garcom: i.orders?.garcons?.nome
          ?? (ehAutoAtendimento ? 'Auto Atendimento' : i.orders?.is_venda_balcao ? 'Balcão' : (ehSalao ? 'Sem Garçom - Venda Direta' : null)),
        venda_balcao: i.orders?.is_venda_balcao ?? false,
        // Status de entrega do pedido (delivery) — usado no Bar pra alerta de motoboy
        // (em trânsito/entregue/ocorrência) e botão de localizar no mapa.
        pedido_status: i.orders?.status ?? null,
        motoboy_lat: i.orders?.motoboy_lat ?? null,
        motoboy_lng: i.orders?.motoboy_lng ?? null,
        delivery_occurrence: i.orders?.delivery_occurrence ?? null,
        // Total/forma de pagamento/criação do PEDIDO (não do item) — só relevante pra
        // delivery/balcão, pra card agrupado por pedido mostrar o mesmo resumo da Cozinha.
        pedido_total: i.orders?.total ?? null,
        pedido_payment_method: i.orders?.payment_method ?? null,
        pedido_created_at: i.orders?.created_at ?? null,
      };
    }),
  };
}

// Move só esse item de "aguardando" (enviado) pra "preparando" — ação por item, não
// por comanda inteira (cada prato tem seu próprio ritmo de preparo).
async iniciarPreparoItem(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();
  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  const { error } = await this.supabase.client
    .from('order_items')
    .update({ status: 'preparando', preparando_em: new Date().toISOString() })
    .eq('id', itemId);
  if (error) throw error;

  return { ok: true };
}

async marcarItemPronto(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, order_id, orders(restaurant_id, canal, status)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  const { error } = await this.supabase.client.from('order_items').update({ status: 'pronto', pronto_em: new Date().toISOString() }).eq('id', itemId);
  if (error) throw error;

  // Pedido de delivery/balcão pode ter itens em praças diferentes (ex: lanche na
  // Cozinha, bebida no Drinks) — cada praça só controla o status dos seus próprios
  // itens. O pedido inteiro só vira 'ready' (libera pro motoboy) quando TODAS as
  // praças envolvidas já marcaram seus itens como prontos, pra não liberar comida
  // que ainda não saiu de outra praça. Comanda de salão não usa esse status
  // ('aberta'/'paga', não 'ready'), então só entra aqui fora do canal presencial.
  const pedido = (item as any).orders;
  if (pedido?.canal !== 'presencial' && ['confirmed', 'preparing'].includes(pedido?.status)) {
    const { data: itensRestantes } = await this.supabase.client
      .from('order_items')
      .select('id, status')
      .eq('order_id', item.order_id)
      .neq('status', 'cancelado');
    const todosProntos = (itensRestantes ?? []).length > 0 && (itensRestantes ?? []).every((i: any) => i.status === 'pronto');
    if (todosProntos) {
      await this.supabase.client.from('orders').update({ status: 'ready', updated_at: new Date().toISOString() }).eq('id', item.order_id);
    }
  }

  return { ok: true };
}

// Desfaz clique errado na Cozinha/Bar — volta um passo (pronto -> preparando ->
// enviado/aguardando). "Enviado" já é o início da fila do KDS, não dá pra voltar mais.
async voltarStatusItem(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, status, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  if (item.status === 'pronto') {
    const { error } = await this.supabase.client
      .from('order_items')
      .update({ status: 'preparando', pronto_em: null })
      .eq('id', itemId);
    if (error) throw error;
    return { ok: true, status: 'preparando' };
  }

  if (item.status === 'preparando') {
    const { error } = await this.supabase.client
      .from('order_items')
      .update({ status: 'enviado', preparando_em: null })
      .eq('id', itemId);
    if (error) throw error;
    return { ok: true, status: 'enviado' };
  }

  throw new BadRequestException('Item já está aguardando — não dá pra voltar mais');
}

// Cancela item ainda "Aguardando Preparo" — some da fila de Produção e Cozinha
// (ambas leem por status via GET /kds). Só permite nesse estágio: depois que a
// cozinha já começou o preparo, cancelar teria que envolver estorno/decisão do
// dono, fora do escopo desse botão rápido.
async cancelarItem(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, status, order_id, product_id, quantity, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  if (item.status !== 'enviado') {
    throw new BadRequestException('Só é possível cancelar um item enquanto está Aguardando Preparo');
  }

  const { error } = await this.supabase.client
    .from('order_items')
    .update({ status: 'cancelado', cancelado_em: new Date().toISOString() })
    .eq('id', itemId);
  if (error) throw error;

  await this.estoque.restaurarItens([{ product_id: item.product_id, quantity: item.quantity }]);

  return { ok: true };
}

// Adiantar/atrasar item na fila "Aguardando Preparo" — troca de posição com o vizinho
// (cima/baixo). Resequencia ordem_fila de TODOS os itens "enviado" do setor pra manter
// consistência: sem isso, itens ainda sem ordem_fila (null) ficariam intercalados de
// forma imprevisível com os já reordenados.
async moverPosicaoItem(itemId: number, restaurantId: number, direcao: 'cima' | 'baixo') {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, status, impressora_id, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }
  if (item.status !== 'enviado') {
    throw new BadRequestException('Só é possível reordenar um item enquanto está Aguardando Preparo');
  }

  const { data: fila, error } = await this.supabase.client
    .from('order_items')
    .select('id, ordem_fila, enviado_em')
    .eq('impressora_id', item.impressora_id)
    .eq('status', 'enviado')
    .order('ordem_fila', { ascending: true, nullsFirst: false })
    .order('enviado_em', { ascending: true });
  if (error) throw error;

  const lista = fila as any[];
  const idx = lista.findIndex((i) => i.id === itemId);
  const swapIdx = direcao === 'cima' ? idx - 1 : idx + 1;
  if (idx === -1 || swapIdx < 0 || swapIdx >= lista.length) {
    throw new BadRequestException('Item já está na ponta da fila');
  }

  [lista[idx], lista[swapIdx]] = [lista[swapIdx], lista[idx]];

  await Promise.all(
    lista.map((i, novaPos) =>
      this.supabase.client.from('order_items').update({ ordem_fila: novaPos }).eq('id', i.id),
    ),
  );

  return { ok: true };
}

private readonly STATUS_ABERTOS = ['pending', 'confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery'];
private readonly COMANDA_STATUS_ABERTOS = ['aberta', 'fechada_garcom'];

// Venda finalizada = entregue (delivery) ou paga (comanda do salão) — sem isso o
// resumo/KPI do dashboard ignorava toda venda do salão (comanda nunca vira 'delivered').
private readonly STATUS_VENDA_FINALIZADA = ['delivered', 'paga'];

// Comanda do salão pode ter N pagamentos com formas diferentes (parcial pelo garçom +
// resto pelo caixa) — orders.payment_method só guarda a última forma usada no
// fechamento, então pra decompor certo o "por forma de pagamento" precisa ir direto
// no ledger de comanda_pagamentos. Delivery continua com pagamento único (sem mudança).
private async buscarPagamentosPorComanda(pedidos: any[]): Promise<Map<number, { order_id: number; valor: number; valor_recebido: number | null; forma_pagamento: string; origem: string; troco: number; criado_em: string; taxa_cartao_valor: number }[]>> {
  const idsComanda = pedidos.filter((p: any) => p.canal === 'presencial').map((p: any) => p.id);
  const mapa = new Map<number, { order_id: number; valor: number; valor_recebido: number | null; forma_pagamento: string; origem: string; troco: number; criado_em: string; taxa_cartao_valor: number }[]>();
  if (!idsComanda.length) return mapa;

  const { data } = await this.supabase.client
    .from('comanda_pagamentos')
    .select('order_id, valor, valor_recebido, forma_pagamento, origem, troco, criado_em, taxa_cartao_valor')
    .in('order_id', idsComanda);

