158	};
159	
160	// Linha de produção do Salão — visão unificada de TODOS os setores (cozinha, bar,
161	// salgados...) num painel só, dono acessa direto logado (sem link/token separado, mesmo
162	// padrão de acesso da tela de Cozinha do delivery). Cada setor é uma impressora
163	// cadastrada; itens vêm de order_items roteados pra ela (ver GET /restaurante/kds),
164	// lista PLANA por item (não agrupa por mesa/comanda), com cronômetro de espera/preparo.
165	const RestauranteProducao = () => {
166	  const navigate = useNavigate();
167	  const [impressoras, setImpressoras] = useState(null);
168	  const [itensPorImpressora, setItensPorImpressora] = useState({});
169	  const [itensSemSetor, setItensSemSetor] = useState([]);
170	  const [restauranteNome, setRestauranteNome] = useState('');
171	  const [loading, setLoading] = useState(true);
172	  const [erro, setErro] = useState(null);
173	  const [lastUpdate, setLastUpdate] = useState(null);
174	  const [comandaAbertaId, setComandaAbertaId] = useState(null);
175	  const now = useNowTick();
176	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
177	  const [verTodosEntregues, setVerTodosEntregues] = useState({}); // { [impressoraId]: bool }
178	  const [busca, setBusca] = useState('');
179	  const prevItemIds = useRef(new Set());
180	  const firstLoad = useRef(true);
181	  const tocarSom = useNotificacaoSonora('cozinha');
182	
183	  useEffect(() => {
184	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
185	    listarImpressoras().then(setImpressoras).catch((e) => setErro(e.message));
186	  }, []);
187	
188	  const carregar = useCallback(async (lista) => {
189	    try {
190	      const [resultados, semSetor] = await Promise.all([
191	        Promise.all(lista.map((imp) => getKdsItensRestaurante(imp.id).then((r) => [imp, r.itens ?? []]))),
192	        getKdsSemImpressora().then((r) => r.itens ?? []).catch(() => []),
193	      ]);
194	      setItensSemSetor(semSetor);
195	      const porImpressora = {};
196	      const idsAgora = new Set();
197	      for (const [imp, itens] of resultados) {
198	        porImpressora[imp.id] = itens;
199	        for (const i of itens) idsAgora.add(i.id);
200	      }
201	
202	      if (!firstLoad.current) {
203	        const novos = [...idsAgora].filter((id) => !prevItemIds.current.has(id));
204	        if (novos.length > 0) tocarSom();
205	      } else {
206	        firstLoad.current = false;
207	      }
208	      prevItemIds.current = idsAgora;
209	
210	      setItensPorImpressora(porImpressora);
211	      setLastUpdate(new Date());
212	      setErro(null);
213	    } catch (e) {
214	      setErro(e.message);
215	    } finally {
216	      setLoading(false);
217	    }
218	  }, [tocarSom]);
219	
220	  useEffect(() => {
221	    if (!impressoras) return;
222	    if (impressoras.length === 0) { setLoading(false); return; }
223	    carregar(impressoras);
224	    const interval = setInterval(() => carregar(impressoras), 15000);
225	    return () => clearInterval(interval);
226	  }, [impressoras, carregar]);
227	
228	  const marcarPronto = async (itemId) => {
229	    await marcarItemProntoRestaurante(itemId);
230	    carregar(impressoras);
231	  };
232	
233	  const iniciarPreparo = async (item) => {
234	    await iniciarPreparoItemRestaurante(item.id);
235	    carregar(impressoras);
236	  };
237	
238	  const voltarItem = async (item) => {
239	    await voltarStatusItemRestaurante(item.id);
240	    carregar(impressoras);
241	  };
242	
243	  const moverItem = async (item, direcao) => {
244	    try {
245	      await moverItemRestaurante(item.id, direcao);
246	      carregar(impressoras);
247	    } catch (e) {
248	      alert(e.message);
249	    }
250	  };
251	
252	  const cancelarItem = async (item) => {
253	    if (!confirm(`Cancelar "${item.product_name}"? Esta ação não pode ser desfeita.`)) return;
254	    try {
255	      await cancelarItemRestaurante(item.id);
256	      carregar(impressoras);
257	    } catch (e) {
258	      alert(e.message);
259	    }
260	  };
261	
262	  const reimprimir = async (item, setorNome) => {
263	    try {
264	      const res = await reimprimirItemRestaurante(item.id);
265	      if (res.via === 'navegador') {
266	        printTicketSetor([item], { mesaLabel: item.mesa, cliente_mesa_nome: item.cliente, numero_comanda: item.numero_comanda }, setorNome);
267	      }
268	    } catch (e) {
269	      setErro(e.message);
270	    }
271	  };
272	
273	  const salvarObservacao = async (item, observacao) => {
274	    try {
275	      await editarItemComandaSalao(item.order_id, item.id, { observacao });
276	      carregar(impressoras);
277	    } catch (e) {
278	      setErro(e.message);
279	    }
280	  };
281	
282	  if (loading) return (
283	    <div className="min-h-screen bg-[#111111] flex items-center justify-center">
284	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
285	    </div>
286	  );
287	
288	  const todosItens = Object.values(itensPorImpressora).flat();
289	  const totalDelivery = todosItens.filter((i) => i.tipo === 'delivery').length;
290	  const totalSalao = todosItens.filter((i) => i.tipo === 'salao').length;
291	  const buscaNormalizada = busca.trim().toLowerCase();
292	  // Leitor de código de barras digita os dígitos zero-padded (ver barcodeValue em
293	  // printComanda.js) e manda Enter — bate exato no numero_comanda, não por substring
294	  // (senão "00000042" nunca acharia a comanda #42).
295	  const numeroComandaEscaneado = /^\d+$/.test(busca.trim()) ? parseInt(busca.trim(), 10) : null;
296	  const passaBusca = (i) => {
297	    if (!buscaNormalizada) return true;
298	    if (numeroComandaEscaneado !== null && i.numero_comanda === numeroComandaEscaneado) return true;
299	    const alvo = [i.cliente, i.mesa, i.mesa_numero, i.numero_comanda, i.garcom]
300	      .filter((v) => v !== null && v !== undefined)
301	      .join(' ')
302	      .toLowerCase();
303	    return alvo.includes(buscaNormalizada);
304	  };
305	  const passaFiltro = (i) => (filtroCanal === 'todos' || i.tipo === filtroCanal) && passaBusca(i);
306	  const totalItens = todosItens.filter(passaFiltro).length;
307	  // Igual à caixa de leitor da Cozinha: verde quando acha a comanda escaneada, vermelho
308	  // quando não acha — só reage ao código exato, busca por nome/mesa/garçom fica neutra.
309	  const itemEncontradoBusca = numeroComandaEscaneado !== null && todosItens.some((i) => i.numero_comanda === numeroComandaEscaneado);
310	  const corBuscaCod = numeroComandaEscaneado === null ? null : itemEncontradoBusca ? 'ok' : 'erro';
311	
312	  return (
313	    <div className="min-h-screen bg-[#111111]">
314	      <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
315	        <div className="flex items-center gap-4">
316	          <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
317	            <Icon name="ArrowLeft" size={18} />
318	          </button>
319	          <div className="flex items-center gap-2">
320	            <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
321	              <Icon name="ChefHat" size={16} className="text-white" />
322	            </div>
323	            <div>
324	              <p className="text-white font-black text-base leading-none">Linha de Produção — Salão</p>
325	              <p className="text-[#71717A] text-xs">{restauranteNome}</p>
326	            </div>
327	          </div>
328	          <div className="ml-auto flex items-center gap-2">
329	            <div className="flex items-center gap-2 text-xs text-[#71717A]">
330	              <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
331	              {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
332	            </div>
333	            <button onClick={() => carregar(impressoras ?? [])} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
334	              <Icon name="RefreshCw" size={16} />
335	            </button>
336	          </div>
337	        </div>
338	
339	        {/* Busca por cliente, mesa, comanda, garçom ou leitor de código de barras — mesma
340	            caixa (cor, botão Buscar, texto de confirmação) da Cozinha */}
341	        <div className={`flex items-center gap-2 mt-3 px-3 py-2 rounded-xl border transition-colors ${
342	          corBuscaCod === 'ok' ? 'border-green-500 bg-green-900/20' :
343	          corBuscaCod === 'erro' ? 'border-red-500 bg-red-900/20' :
344	          'border-[#2A2A2A] bg-[#111111] focus-within:border-[#FF441F]'
345	        }`}>
346	          <Icon name="ScanLine" size={16} className={`flex-shrink-0 ${corBuscaCod === 'ok' ? 'text-green-400' : corBuscaCod === 'erro' ? 'text-red-400' : 'text-[#71717A]'}`} />
347	          <input
348	            type="text"
349	            value={busca}
350	            onChange={(e) => setBusca(e.target.value)}
351	            placeholder="Buscar por cliente, mesa, comanda, garçom ou aponte o leitor..."
352	            className="flex-1 bg-transparent text-white text-sm placeholder:text-[#3A3A3A] outline-none"
353	          />
354	          {busca && (
355	            <>
356	              <button
357	                onClick={() => {
358	                  const alvo = todosItens.find((i) => i.numero_comanda === numeroComandaEscaneado);
359	                  if (alvo) document.getElementById(`salao-item-${alvo.id}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
360	                }}
361	                className="flex-shrink-0 px-3 py-1 bg-[#FF441F] text-white text-xs font-bold rounded-lg hover:bg-[#E63A19]">
362	                Buscar
363	              </button>
364	              <button onClick={() => setBusca('')} className="text-[#71717A] hover:text-white flex-shrink-0">
365	                <Icon name="X" size={15} />
366	              </button>
367	            </>
368	          )}
369	        </div>
370	        {corBuscaCod && (
371	          <p className={`text-xs font-semibold mt-1.5 ${corBuscaCod === 'ok' ? 'text-green-400' : 'text-red-400'}`}>
372	            {corBuscaCod === 'ok' ? `Comanda #${numeroComandaEscaneado} encontrada` : `Comanda #${numeroComandaEscaneado} não encontrada`}
373	          </p>
374	        )}
375	
376	        {/* Filtro de canal — Todos/Delivery/Salão */}
377	        <div className="flex items-center gap-2 mt-3">
378	          {[
379	            { key: 'todos', label: 'Todos', count: totalDelivery + totalSalao },
380	            { key: 'delivery', label: 'Delivery', count: totalDelivery },
381	            { key: 'salao', label: 'Salão', count: totalSalao },
382	          ].map((f) => (
383	            <button
384	              key={f.key}
385	              onClick={() => setFiltroCanal(f.key)}
386	              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
387	                filtroCanal === f.key
388	                  ? 'bg-[#FF441F] text-white'
389	                  : 'bg-[#111111] text-[#71717A] border border-[#2A2A2A] hover:text-white'
390	              }`}
391	            >
392	              {f.label}
393	              <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${filtroCanal === f.key ? 'bg-white/20' : 'bg-[#2A2A2A]'}`}>{f.count}</span>
394	            </button>
395	          ))}
396	        </div>
397	      </header>
398	
399	      {erro && (
400	        <div className="mx-5 mt-4 bg-red-900/50 border border-red-700 rounded-xl px-4 py-3 text-sm text-red-400">{erro}</div>
401	      )}
402	
403	      {/* Itens enviados que nunca chegaram em setor nenhum — produto sem impressora
404	          configurada no cadastro. Some sozinho da lista assim que reenviado. */}
405	      {itensSemSetor.length > 0 && (
406	        <div className="mx-5 mt-4 bg-yellow-900/20 border border-yellow-600/40 rounded-2xl p-4">
407	          <div className="flex items-center gap-2 mb-3">
408	            <Icon name="AlertTriangle" size={16} className="text-yellow-400" />
409	            <h2 className="text-yellow-400 font-bold text-sm">
410	              {itensSemSetor.length} {itensSemSetor.length === 1 ? 'item não chegou' : 'itens não chegaram'} na cozinha (sem impressora configurada)
411	            </h2>
412	          </div>
413	          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
414	            {itensSemSetor.map((item) => (
415	              <ItemSemSetorCard key={item.id} item={item} impressoras={impressoras ?? []} onReenviado={() => carregar(impressoras)} />
416	            ))}
417	          </div>
418	        </div>
419	      )}
420	
421	      {impressoras && impressoras.length === 0 ? (
422	        <div className="text-center py-20 px-5">
423	          <Icon name="Printer" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
424	          <p className="text-[#71717A] text-lg font-semibold">Nenhuma impressora cadastrada</p>
425	          <p className="text-[#3A3A3A] text-sm mt-1">Cada setor (Cozinha, Bar, Salgados...) precisa de uma impressora cadastrada com esse setor.</p>
426	          <button onClick={() => navigate('/restaurante/impressoras')}
427	            className="mt-4 px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19]">
428	            Ir pra Impressoras
429	          </button>
430	        </div>
431	      ) : (
432	        <main className="p-5 max-w-6xl mx-auto space-y-8">
433	          {(impressoras ?? []).map((imp) => {
434	            const itens = (itensPorImpressora[imp.id] ?? []).filter(passaFiltro);
435	            const aguardando = itens.filter((i) => i.status === 'enviado');
436	            const preparando = itens.filter((i) => i.status === 'preparando');
437	            const entregues = itens
438	              .filter((i) => i.status === 'pronto')
439	              .sort((a, b) => new Date(b.pronto_em).getTime() - new Date(a.pronto_em).getTime());
440	            return (
441	              <div key={imp.id}>
442	                <div className="flex items-center gap-2 mb-3">
443	                  <div className="w-2.5 h-2.5 rounded-full bg-orange-400" />
444	                  <h2 className="text-white font-bold text-sm uppercase tracking-wider">{imp.setor}</h2>
445	                  {itens.length > 0 && (
446	                    <span className="bg-orange-500 text-white text-xs font-black px-2 py-0.5 rounded-full">
447	                      {itens.length}
448	                    </span>
449	                  )}
450	                </div>
451	                {itens.length === 0 ? (
452	                  <div className="rounded-2xl border-2 border-dashed border-[#2A2A2A] p-6 text-center mb-2">
453	                    <p className="text-[#71717A] text-sm">Nenhum item pendente em {imp.setor}</p>
454	                  </div>
455	                ) : (
456	                  <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
457	                    <div>
458	                      <p className="text-xs font-bold text-blue-400 uppercase tracking-wider mb-2">Aguardando Preparo</p>
459	                      {aguardando.length === 0 ? (
460	                        <p className="text-xs text-[#71717A]">Nenhum</p>
461	                      ) : (
462	                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
463	                          {aguardando.map((item, idx) => (
464	                            <SalaoItemCard key={item.id} item={item} posicao={idx + 1} now={now}
465	                              ehPrimeiro={idx === 0} ehUltimo={idx === aguardando.length - 1} onMover={moverItem}
466	                              onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} onCancelar={cancelarItem} onAbrirComanda={setComandaAbertaId} onSalvarObservacao={salvarObservacao}
467	                              highlighted={numeroComandaEscaneado !== null && item.numero_comanda === numeroComandaEscaneado} />
468	                          ))}
469	                        </div>
470	                      )}
471	                    </div>
472	                    <div>
473	                      <p className="text-xs font-bold text-orange-400 uppercase tracking-wider mb-2">Em Preparo</p>
474	                      {preparando.length === 0 ? (
475	                        <p className="text-xs text-[#71717A]">Nenhum</p>
476	                      ) : (
477	                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
478	                          {preparando.map((item, idx) => (
479	                            <SalaoItemCard key={item.id} item={item} posicao={idx + 1} now={now}
480	                              onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} onAbrirComanda={setComandaAbertaId} onSalvarObservacao={salvarObservacao}
481	                              highlighted={numeroComandaEscaneado !== null && item.numero_comanda === numeroComandaEscaneado} />
482	                          ))}
483	                        </div>
484	                      )}
485	                    </div>
486	                    <div>
487	                      <p className="text-xs font-bold text-emerald-400 uppercase tracking-wider mb-2">Entregues hoje</p>
488	                      {entregues.length === 0 ? (
489	                        <p className="text-xs text-[#71717A]">Nenhum</p>
490	                      ) : (
491	                        <>
492	                          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-3">
493	                            {(verTodosEntregues[imp.id] ? entregues : entregues.slice(0, 2)).map((item, idx) => (
494	                              <SalaoItemCard key={item.id} item={item} posicao={idx + 1} now={now}
495	                                onReimprimir={(it) => reimprimir(it, imp.setor)} onIniciarPreparo={iniciarPreparo} onMarcarPronto={marcarPronto} onVoltar={voltarItem} onAbrirComanda={setComandaAbertaId} onSalvarObservacao={salvarObservacao}
496	                                highlighted={numeroComandaEscaneado !== null && item.numero_comanda === numeroComandaEscaneado} />
497	                            ))}
498	                          </div>
499	                          {entregues.length > 2 && (
500	                            <button onClick={() => setVerTodosEntregues((v) => ({ ...v, [imp.id]: !v[imp.id] }))}
501	                              className="mt-3 w-full py-2 text-xs font-bold text-emerald-400 border border-emerald-500/30 rounded-xl hover:bg-emerald-500/10">
502	                              {verTodosEntregues[imp.id] ? 'Recolher / fechar a lista' : `Ver todos (${entregues.length})`}
503	                            </button>
504	                          )}
505	                        </>
506	                      )}
507	                    </div>
508	                  </div>
509	                )}
510	              </div>
511	            );
512	          })}
513	          {totalItens === 0 && (
514	            <div className="text-center py-16">
515	              <Icon name="UtensilsCrossed" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
516	              <p className="text-[#71717A] text-lg font-semibold">Tudo tranquilo</p>
517	              <p className="text-[#3A3A3A] text-sm mt-1">Nenhum item pendente em nenhum setor agora</p>
518	            </div>
519	          )}
520	        </main>
521	      )}
522	
523	      <p className="text-center text-xs text-[#3A3A3A] py-4">Atualiza automaticamente a cada 15 segundos</p>
524	
525	      {comandaAbertaId && (
526	        <ComandaModal orderId={comandaAbertaId} impressoras={impressoras ?? []} onFechar={() => setComandaAbertaId(null)}
527	          onItemReenviado={() => carregar(impressoras)} />
528	      )}
529	    </div>
530	  );
531	};
532	
533	export default RestauranteProducao;
