    } finally {
      setDeletandoCateg(null);
    }
  };

  const fecharModal = () => {
    setShowModal(false);
    setEditando(null);
    setForm(EMPTY_FORM);
  };

  const abrirImportModal = () => {
    setJsonImport('');
