const signIn = async (email, password) => {
  setAuthError(null)
  setLoading(true)

  try {
    const { data, error } = await supabase?.auth?.signInWithPassword({
      email,
      password
    })

    if (error) {
      setAuthError(error?.message)
      return { success: false, error: error?.message };
    }

    return { success: true, user: data?.user };
  } catch (error) {
    if (error?.message?.includes('Failed to fetch') || 
        error?.message?.includes('AuthRetryableFetchError')) {
      setAuthError('Cannot connect to authentication service. Your Supabase project may be paused or inactive. Please check your Supabase dashboard and resume your project if needed.')
      return { success: false, error: 'Connection failed' }
    }

    setAuthError('Something went wrong. Please try again.')
    return { success: false, error: 'Authentication failed' }
  } finally {
    setLoading(false)
  }
}

const signUp = async (email, password, userData = {}) => {
  setAuthError(null)
  setLoading(true)

  try {
    const { data, error } = await supabase?.auth?.signUp({
      email,
      password,
      options: {
        data: {
          name: userData?.name || email?.split('@')?.[0],
          role: userData?.role || 'customer',
          ...userData
        }
      }
    })

    if (error) {
      setAuthError(error?.message)
      return { success: false, error: error?.message };
    }

    return { success: true, user: data?.user };
  } catch (error) {
    if (error?.message?.includes('Failed to fetch') || 
        error?.message?.includes('AuthRetryableFetchError')) {
      setAuthError('Cannot connect to authentication service. Your Supabase project may be paused or inactive. Please check your Supabase dashboard and resume your project if needed.')
      return { success: false, error: 'Connection failed' }
    }

    setAuthError('Something went wrong. Please try again.')
    return { success: false, error: 'Registration failed' }
  } finally {
    setLoading(false)
  }
}

const signOut = async () => {
  setLoading(true)
  try {
    const { error } = await supabase?.auth?.signOut()
    if (error) {
      setAuthError(error?.message)
    }
    setUser(null)
    setUserProfile(null)
    setPlanoStatus(null)
  } catch (error) {
    setAuthError('Failed to sign out')
  } finally {
    setLoading(false)
  }
}

const clearError = () => setAuthError(null)

// Recarrega o perfil do banco — usado quando algo fora do fluxo normal de
// login muda o role da conta (ex: cadastro de motoboy promove pra 'motoboy').
const refreshUserProfile = () => {
  if (user?.id) return fetchUserProfile(user.id)
  return Promise.resolve()
}

const isAdmin = () => {
  return userProfile?.role === 'admin'
}

const isRestaurantOwner = () => {
  return userProfile?.role === 'restaurant_owner'
}

const isMotoboy = () => {
  return userProfile?.role === 'motoboy'
}

const isAuthenticated = () => {
  return !!user
}

const value = {
  user,
  userProfile,
  loading,
  authError,
  signIn,
  signUp,
  signOut,
  clearError,
  isAdmin,
  isRestaurantOwner,
  isMotoboy,
  isAuthenticated,
  refreshUserProfile,
  planoStatus,
  refreshPlanoStatus
}

