@Injectable()
export class AuthLoginService {
  // Cliente à parte (chave anon, sem persistir sessão) só pra verificar a senha —
  // NUNCA reaproveitar this.supabase.client (service_role) pra isso: signInWithPassword
  // guarda a sessão logada dentro do próprio client, e como o client do SupabaseService
  // é um singleton compartilhado por toda a aplicação, logar um usuário nele
  // sequestraria a "identidade" usada por TODAS as outras queries service_role em
  // andamento em outras requisições — risco sério de vazamento de dados entre requests.
  private readonly authClient: SupabaseClient;

  constructor(
    private supabase: SupabaseService,
    private config: ConfigService,
  ) {
    this.authClient = createClient(
      this.config.getOrThrow('SUPABASE_URL'),
      this.config.getOrThrow('SUPABASE_ANON_KEY'),
      { auth: { persistSession: false, autoRefreshToken: false } },
    );
  }

