        <div className="max-w-md mx-auto space-y-6">

          {/* Card principal */}
          <div className="bg-white dark:bg-[#27272A] rounded-2xl shadow-sm border border-[#E4E4E7] dark:border-[#3F3F46] p-6 space-y-5">
