                onForgotPassword={() => setShowForgotPassword(true)}
                loading={loading}
                primaryColor="#2563EB"
              />
            ) : (
              <RegisterForm
                onRegister={handleRegister}
                loading={loading}
                primaryColor="#2563EB"
              />
            )}
